// Generated from dialogues/animals/*.json and dialogues/branches.json. Run node dialogues/build-bundle.cjs after edits.
window.FARM_DIALOGUES = {"animals":{"cat":{"name":"貓","nextCharacter":"crow","normal":["喵～曬太陽真舒服。羊上次幫我在穀倉留了好位子，牠是隻好羊。","不過受傷就要老實擦藥，逞強裝沒事，身上的味道只會把真正的野狼引過來喔。"],"panicked":["喵嗷——！全場都在傳羊說的話，說今晚大家都要完蛋了，弄得我也好緊張！","嘶——！別吵我！我在練習磨爪子防身！"],"comforted":"呼嚕呼嚕……抓抓下巴真舒服。羊就是愛面子嘛。我剛才在屋頂上看到「西北邊枯井」旁邊有踩碎的樹枝喔！","injured":"喵嗚……從樹上掉下來扭到手手了，不能跳了啦……","post_rescue":"紅農舍的軟墊好舒服喔。西北枯井旁邊雜草很多，在那裡放夾子，野狼絕對看不見！"},"chicken":{"name":"雞","nextCharacter":"duck","normal":["咕咕、咯咯！羊最照顧大家了，上次牧草不夠時，牠還幫忙勻出飼料給我們。","看到羊一跛一跛的，我都快哭了……野狼怎麼這麼壞啦！"],"panicked":["咯咯噠——！羊說大野狼要攻打東門，可是我的雞舍在最南邊耶！沒有大家保護我該怎麼辦啦！","不要抓我！我只是一顆長著羽毛的羽毛球！"],"comforted":"咯咯……呼，謝謝你抱住我。昨晚抓門的聲音真的在「南邊雞舍正後方」，那邊圍籬破了個洞！","injured":"咕咕……羽毛被撕掉好多根，屁股好痛喔，走不動了……","post_rescue":"咕咕噠！擦了藥好舒服喔！把夾子放在雞舍後面的小草堆裡，野狼想偷溜進來就會被夾住！"},"cow":{"name":"牛","nextCharacter":"horse","suspicious":["哞……羊說的路線一直變來變去，我們是不是應該先查證，而不是跟著牠跑？"],"normal":["哞～上次沒有牧草時，多虧羊想辦法，大家都很謝謝牠。","看牠一跛一跛的真讓人心疼，到底是什麼壞野狼把牠打傷的？"],"panicked":["哞嗷嗷！羊剛才親口跟我說大野狼要來了！連羊都這麼說，今晚一定大難臨頭了！","你們別靠近我，我要把草棚的大門全部用稻草堵死！"],"comforted":"呼……深呼吸一下。你說得對，羊有時候也是會愛面子的。我昨晚聞到的臭味確實是從「北邊樹林」飄過來的！","injured":"哎唷……腿被抓傷了，站不起來了……快扶我進紅農舍……","post_rescue":"謝謝你幫我包紮。北邊小路又窄又臭，把大鐵夾放路中間，大野狼一定踩上去！"},"crow":{"name":"烏鴉","nextCharacter":"sparrow","normal":["嘎——嘎！平時最聰明的羊，今天怎麼像個鴨子一樣一扭一扭的？笑死我了！","我知道牠的秘密喔～但我不說！聰明的羊也有出糗的時候，嘻嘻！"],"panicked":["嘎啊！地上的笨蛋們全相信羊的東門作戰，把森林的野狼引暴躁了！枯樹都在搖晃啦！","樹要倒了！世界末日了！嘎嘎嘎！"],"comforted":"嘎……摸摸頭真舒服。看在你誠懇的份上：昨晚羊是溜去後山採野莓啦！但牠跌倒的「北邊水溝」，剛好就是野狼來的小路！","injured":"撲稜撲稜……翅膀被樹枝拉傷了，掉在地上飛不起來啦……","post_rescue":"嘎——！翅膀擦了亮晶晶藥膏真帥氣！天黑時野狼一定會從北邊水溝衝出來，在那裡放兩個大鐵夾！"},"dog":{"name":"狗","nextCharacter":"cat","suspicious":["汪！我守門這麼久，沒聞到泥坑和池塘都有狼味。羊的說法很可疑！"],"normal":["汪汪！我很敬佩羊解決過牧草危機，但巡邏是我的工作！","牠今天走路怪怪的，說是跟狼打架……可我怎麼聞到牠後腿有一股臭水溝泥巴味道啊？"],"panicked":["嗚嗚……汪！大家把羊的話當真，全擠在東門，西門根本沒人顧！我一隻狗怎麼看守啦！","大家冷靜一點！聽我看守的經驗好不好！"],"comforted":"汪！謝謝你願意聽我說！羊太愛面子了，不好意思承認自己跌倒啦。「西邊木門」下面有個破洞，那裡真的有狼味！","injured":"嗷嗚……鼻子被抓了一把，流血了啦……快帶我去紅農舍擦藥……","post_rescue":"汪！精神來了！羊也是怕丟臉才吹牛的，大家別怪牠，今晚我們一起抓野狼！"},"duck":{"name":"鴨","nextCharacter":"goose","normal":["呱呱！羊上次教我們在乾旱時挖深水塘，牠好聰明喔！","羊說野狼好大一隻，我也想幫忙，但我只有兩隻短短的腳蹼……"],"panicked":["呱啊啊！大家都跟著羊往東門跑，水塘都被踩扁了！我不知道該躲去哪裡啦！","不要拉我的腳蹼！水裡有怪物啦！"],"comforted":"呱……摸摸羽毛好安心喔。大家太慌張了對不對？其實我昨天在「東邊水閘門」的淺水灘看到漂著幾根狼毛喔！","injured":"呱嗚……腳蹼被石頭割破了，游不快了啦……","post_rescue":"呱呱！農舍裡有小碎玉米，謝謝你。水邊的影子看起來很巨大，但我沒看清那是什麼；請再找烏鴉查證。"},"goose":{"name":"鵝","nextCharacter":"crow","normal":["浹——！頭抬高、胸部挺起來！雖然羊上次解決了牧草危機值得誇獎，但水塘還是我說了算！","牠說牠單挑野狼？哼，這話聽起來怪怪的，我看八成是自己跌倒嘴硬吧！"],"panicked":["浹浹浹！全場都在傳羊的戰鬥故事，把我的隊伍搞得亂七八糟！氣死我了！","退後！通通退後！誰敢靠近我就啄誰！"],"comforted":"哼……算你識相，還知道拿新鮮菜葉來安撫我。昨晚我確實看見黑影沿著「東北邊蘆葦叢」摸進來，注意那裡！","injured":"哎唷……脖子被抓傷了，快點帶我去紅農舍！","post_rescue":"咳咳……農舍的軟墊挺舒服的。池塘倒影會把小影子放得很大；確認足跡再決定網夾的位置。"},"horse":{"name":"馬","nextCharacter":"dog","normal":["嘶——！羊上次規劃的運草路線很厲害，我很佩服牠！","不過牠說牠踢飛了野狼？奇怪了，論踢腿全農場誰能踢得過我？牠哪時候學會後踢的？"],"panicked":["嘶！羊說大野狼跑得比我還要快十倍！那我怎麼跑得贏啦？！","不要站在我後面！我現在很緊張，隨時會踢人喔！"],"comforted":"呼嚕嚕……摸摸鬃毛好多了。我就說嘛，哪有狼跑那麼快的！聽好囉，「西邊草地」那邊風很大，牠們會順風衝過來！","injured":"腳好痛喔……馬蹄鐵掉了，跑不動了啦……","post_rescue":"多虧有繃帶綁好！在西邊草地的小木橋上放獸夾，野狼順風衝過來絕對煞不住車！"},"pig":{"name":"豬","nextCharacter":"dog","suspicious":["呼嚕……等等，羊每次都說狼在不同地方，泥坑、池塘、東邊柵欄怎麼可能同時都有狼？","我開始懷疑羊了。牠說得越急，大家就越不敢靠近那些地方。"],"normal":["呼嚕嚕……上次草不夠吃，多虧羊幫忙算分配，大家才沒挨餓。","連那麼聰明的羊都被野狼打傷，外面的野狼一定超級兇對不對？"],"panicked":["哇啊啊！羊說狼要從東門打過來了！羊說的一定沒錯！大家快逃啊！","走開走開！我要挖個泥巴洞把自己藏起來，我才不要被狼抓走！"],"comforted":"呼……拍拍肚子。你說羊剛才講話眼睛在亂飄？咦……不過昨晚菜園旁邊的「東南矮圍牆」確實破了個大洞呢。","injured":"痛痛痛！我的小尾巴被咬到了啦！走不動了，快送我去紅農舍！","post_rescue":"農舍好溫暖喔。雖然羊很聰明，但昨晚的聲音真的在「東南矮圍牆」那邊，大鐵夾放那裡就對了！"},"pigeon":{"name":"鴿子","nextCharacter":"sheep","normal":["咕、咕、咕。羊這孩子是我們看著長大的，心腸好、腦子靈，就是自尊心強了點。","大家太相信牠了，所以牠說什麼大家就信什麼。這時候更需要冷靜下來看清真相啊。"],"panicked":["咕哇！全場動物都跟著羊在恐慌，我的心臟快受不了了！大家都盲目了啊！","咳咳咳！老骨頭經不起嚇啦！"],"comforted":"咕……喝口溫水順順氣。謝謝你。再聰明的孩子也是會犯錯的，別苛責牠。今晚野狼會從北渠、西門、東南、南果園四路過來，都要防守好。","injured":"哎唷……老翅膀折到了，掉在穀倉旁邊動不了……","post_rescue":"咕咕……感謝救命。五個網夾要省著用，先問清楚哪條路真的有狼跡，再決定放在哪裡。"},"sheep":{"name":"羊","nextCharacter":"cow","normal":["哎喲……痛痛痛！我才沒事呢！我可是上次幫大家解決牧草危機的羊！","我這條腿是昨晚在樹林裡跟大野狼打架弄傷的！我一腳就把牠踢飛了，牠們今晚要從東門衝進來，大家快去東邊！"],"rumor_spread":"牛！連我都差點受重傷，大野狼真的很可怕，你今晚千萬不能留在空地上！","panicked":["（小聲自言自語）慘了……大家怎麼全部當真了！昨晚的事要是被發現，我該怎麼辦……"],"injured":"嗚嗚嗚……好痛喔！這次不是扭傷，是真的有黑影咬我！快帶我回紅農舍擦藥！","post_rescue":"謝謝你救我……昨晚的事我還沒勇氣說。請先問鴿子、鴨子和烏鴉，再回來找我。","afterTruth":["我終於承認自己說謊了。北邊的狼爪印是真的，但我沒有跟狼打架。","大家願意再聽我說話，這次我要先查證，再開口。"]},"sparrow":{"name":"麻雀","nextCharacter":"pigeon","normal":["啾啾！羊最厲害了！上次沒有牧草時，全靠牠幫大家算好分量，我們才沒挨餓！","看到牠一跛一跛受傷，大家都好緊張喔，我也好想幫牠吹吹痛痛飛走！"],"panicked":["啾啾啾——！羊說野狼有一百隻！連果樹都要被啃光！那我住哪裡啦！","不要看我！我只是一顆毛線球，我很難吃喔！"],"comforted":"啾……摸摸小肚子好溫暖喔。羊每次緊張就會把數字誇大十倍，嘻嘻。不過「南邊廢果園」那邊真的有大腳印喔！","injured":"啾嗚……小爪子被刺草扎破了，走不動了，好痛喔……","post_rescue":"啾！農舍的小米真好吃！南邊果園有兩顆大石頭，中間的路窄窄的，把夾子放那裡剛剛好！"}},"branches":{"evidence":{"night_out":"信鴿記下：昨夜黑鼻羊獨自走出農舍，往北邊去了。","duck_shadow":"鴨子在池塘看見比狼還大的影子；這只能證明牠看見影子，不能證明是狼。","crow_tracks":"烏鴉從空中看見：北渠有羊蹄印和另一組狼爪印，兩者沒有打鬥痕跡。","sheep_truth":"三份證詞對上了：黑鼻羊承認去採莓果、跌進北渠，並沒有和狼單挑。"},"clues":{"north":"北方：臭水溝有狼爪印，可能是入口。","west":"西方：木門下有新鮮狼味。","southeast":"東南方：矮圍牆有可鑽入的破洞。","south":"南方：廢果園的草叢被壓倒。"},"rescueGrants":{"pig":["southeast"],"cow":["north"],"horse":["west"],"dog":["west"],"chicken":["south"],"crow":["north"],"sparrow":["south"]},"conversations":{"sheep":[{"id":"sheep-claim","route":"truth","text":"我昨晚在森林跟野狼單挑，牠們今晚只會從東門來！我腿上的泥？那是打鬥沾的。","nextCharacter":"pigeon"},{"id":"sheep-confession","route":"truth","requires":["night_out","duck_shadow","crow_tracks"],"grants":["sheep_truth","north"],"text":"好吧，我昨晚偷跑出去採莓果，跌進北邊臭水溝。那裡有狼腳印，可我根本沒和狼打架；我怕大家又不信我，才編出單挑的故事。","nextCharacter":"dog"}],"pig":[{"id":"pig-wall","route":"defense","grants":["southeast"],"text":"我看見東南矮圍牆破了一個洞，這是能查證的入口。黑鼻羊說泥坑、池塘和東柵欄都有狼，我可不敢再往那幾處去！","nextCharacter":"dog"}],"cow":[{"id":"cow-north","route":"defense","grants":["north"],"text":"北邊臭水溝吹來狼味。羊說只會從東門來，可我不敢只防一邊。先去問高處巡看的烏鴉吧。","nextCharacter":"crow"}],"horse":[{"id":"horse-west","route":"defense","grants":["west"],"text":"西邊木門附近的蹄聲不對。狗守在那裡，問牠能不能跑快些巡邏。","nextCharacter":"dog"}],"dog":[{"id":"dog-patrol","route":"defense","grants":["west","dog_patrol"],"text":"西門下方有狼味。我現在加快腳步巡遍莊園；夜裡一看見狼，就追上去把牠趕走！","nextCharacter":"pigeon"},{"id":"dog-doubt","route":"truth","requires":["night_out"],"text":"羊腿上是臭水溝的泥，不像和狼纏鬥留下的痕跡。去問昨晚在高空巡看的烏鴉。","nextCharacter":"crow"}],"cat":[{"id":"cat-warning","route":"defense","text":"受傷的夥伴會引來狼，兩回合內務必抱回紅農舍治療。獸夾一共五個，壞了就沒辦法修。","nextCharacter":"chicken"}],"chicken":[{"id":"chicken-south","route":"defense","grants":["south"],"text":"我在南邊雞舍後面的廢果園聽到草叢壓倒的聲音。看看麻雀是否也聽到了。","nextCharacter":"sparrow"}],"duck":[{"id":"duck-monster","route":"truth","grants":["duck_shadow"],"text":"昨夜池塘旁有個比狼還大的怪物影子！可是水面一直晃，我只看見影子，沒看清牠是誰。羊說的東門狼，會不會根本不是那個影子？","nextCharacter":"crow"},{"id":"duck-water","route":"defense","text":"水閘旁有水痕，但不能光憑這個就說狼一定從池塘來。別把羊的猜測當成足跡。","nextCharacter":"goose"}],"goose":[{"id":"goose-doubt","route":"truth","requires":["duck_shadow"],"text":"我守著池塘，鴨子說的巨大怪物只有倒影。先查證腳印，別跟著黑鼻羊的謠言亂跑。","nextCharacter":"crow"}],"crow":[{"id":"crow-tracks","route":"truth","requires":["night_out"],"grants":["crow_tracks","north","crow_guard"],"text":"嘎！我昨晚從北渠上空看見羊蹄印和狼爪印，沒有搏鬥留下的亂痕。我還俯衝去找那頭狼單挑，牠躲進林裡了。今晚我會再從空中牽制牠。","nextCharacter":"sheep"},{"id":"crow-watch","route":"defense","grants":["north","crow_guard"],"text":"我在北邊臭水溝上空看見狼爪印。今晚我會留在高處，發現狼就俯衝牽制。","nextCharacter":"pigeon"}],"sparrow":[{"id":"sparrow-orchard","route":"defense","grants":["south"],"text":"南邊廢果園有被壓倒的草，還聽見重重的腳步。從那條窄路進來最容易踩到網夾。","nextCharacter":"pigeon"}],"pigeon":[{"id":"pigeon-record","route":"truth","grants":["night_out"],"text":"我記下昨晚的事：月亮剛升起時，黑鼻羊獨自離開農舍，往北邊走；天亮前牠才帶著泥巴回來。牠說整夜都在和狼打架，時間對不上。","nextCharacter":"duck"},{"id":"pigeon-routes","route":"defense","text":"我們需要把每個入口的證詞分開記錄：北渠、西門、東南破牆、南果園。查到哪處再往哪處放網夾。","nextCharacter":"pig"}]}}};
